#ifndef PHARAOH_SCENARIO_MISSION_SCENE_PROGRAM_H
#define PHARAOH_SCENARIO_MISSION_SCENE_PROGRAM_H
#include "pharaoh/scenario/mission_scene.h"
#include "pharaoh/runtime/trade_recommendations.h"
#include "pharaoh/runtime/map_ring.h"

/* Persistent program-data owner. Ring/distance tables are generated by their
 * real C initializer; no runtime native address or serialized pointer is used. */
typedef struct PharaohMissionSceneProgramData PharaohMissionSceneProgramData;

/* Call once after real model/SG3 loading and retain this owner. Trade limits
 * come from the actual loaded trade_recommends model, never its BSS zeros.
 * Active monument scene tables remain explicitly absent: mission_scene only
 * admits Nubt's no-active-building/no-monument-goal path. */
PharaohMissionSceneProgramData *pharaoh_mission_scene_program_create(
    const PharaohCampaignIndex *campaign,const uint32_t (*export_limits)[6]);
const PharaohMissionSceneProgram *pharaoh_mission_scene_program_data(
    const PharaohMissionSceneProgramData *data);
void pharaoh_mission_scene_program_destroy(PharaohMissionSceneProgramData *data);
#endif
